import java.util.Scanner;

public class Main {
    public static long computePowerMod(long base, long exp) {
        final long MOD = 1000000007;
        long result = 1;
        for (; exp > 0; exp--) {
            result = (result * base) % MOD;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long p = scanner.nextLong();
        long k = scanner.nextLong();
        long power;

        if (k == 0) {
            power = p - 1;
        } else if (k == 1) {
            power = p;
        } else {
            long x = k;
            long count = 1;
            while (x != 1) {
                x = (x * k) % p;
                count++;
            }
            power = (p - 1) / count;
        }

        System.out.println(computePowerMod(p, power));
        scanner.close();
    }
}
